package main

import (
	"bytes"
	"embed"
	"fmt"
	"go/format"
	"os"
	"strings"
	"text/template"

	"github.com/bahriya-cloud/terraform-provider-bahriya/internal/bmap"
	"github.com/bahriya-cloud/terraform-provider-bahriya/internal/engine"
)

//go:embed templates/*.tmpl
var templateFS embed.FS

// kindFile is a kind's generated file: its schema, rendered from the same
// tree the engine builds at runtime, and its constructor.
func kindFile(name, goName string) ([]byte, error) {
	k := bmap.Embedded().Kind(name)
	if k == nil {
		return nil, fmt.Errorf("kind %s is missing from resource-schema.json", name)
	}
	attrs, err := engine.Attributes(k)
	if err != nil {
		return nil, err
	}
	stringEnum, intEnum := engine.Imports(attrs)
	needsTypes := strings.Contains(engine.RenderAttributes(attrs, 2), "types.")

	var b strings.Builder
	b.WriteString("// Code generated by cmd/generator from resource-schema.json. DO NOT EDIT.\n\npackage resources\n\nimport (\n")
	if stringEnum {
		b.WriteString("\t\"github.com/hashicorp/terraform-plugin-framework-validators/stringvalidator\"\n")
	}
	if intEnum {
		b.WriteString("\t\"github.com/hashicorp/terraform-plugin-framework-validators/int64validator\"\n")
	}
	b.WriteString("\t\"github.com/bahriya-cloud/terraform-provider-bahriya/internal/engine\"\n")
	b.WriteString("\t\"github.com/hashicorp/terraform-plugin-framework/resource\"\n")
	b.WriteString("\t\"github.com/hashicorp/terraform-plugin-framework/resource/schema\"\n")
	if stringEnum || intEnum {
		b.WriteString("\t\"github.com/hashicorp/terraform-plugin-framework/schema/validator\"\n")
	}
	if needsTypes {
		b.WriteString("\t\"github.com/hashicorp/terraform-plugin-framework/types\"\n")
	}
	b.WriteString(")\n\n")
	fmt.Fprintf(&b, "// New%[1]sResource is bahriya_%[2]s, served by the engine.\nfunc New%[1]sResource() resource.Resource {\n\treturn engine.NewResource(%[2]q, %[3]sSchema())\n}\n\n", goName, name, lowerFirst(goName))
	desc := engine.Description(name)
	fmt.Fprintf(&b, "// %sSchema is bahriya_%s's schema.\nfunc %sSchema() schema.Schema {\n\treturn schema.Schema{\n\t\tVersion: engine.SchemaVersion,\n\t\tDescription: %q,\n\t\tMarkdownDescription: %q,\n\t\tAttributes: %s,\n\t}\n}\n",
		lowerFirst(goName), k.TypeName(), lowerFirst(goName), desc, desc, engine.RenderAttributes(attrs, 2))
	return []byte(b.String()), nil
}

func attachmentFile(att AttachmentResource) ([]byte, error) {
	tmpl, err := template.ParseFS(templateFS, "templates/attachment.go.tmpl")
	if err != nil {
		return nil, fmt.Errorf("parse attachment template: %w", err)
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, att); err != nil {
		return nil, fmt.Errorf("execute attachment template for %s: %w", att.Name, err)
	}
	return buf.Bytes(), nil
}

// registryFile lists every resource constructor for the provider.
func registryFile() []byte {
	var b strings.Builder
	b.WriteString("// Code generated by cmd/generator. DO NOT EDIT.\n\npackage resources\n\nimport \"github.com/hashicorp/terraform-plugin-framework/resource\"\n\n")
	b.WriteString("// All returns the set of resource constructors for the Bahriya provider.\nfunc All() []func() resource.Resource {\n\treturn []func() resource.Resource{\n")
	for _, k := range kinds {
		fmt.Fprintf(&b, "\t\tNew%sResource,\n", k.GoName)
	}
	for _, name := range attachments {
		fmt.Fprintf(&b, "\t\tNewProject%sAttachmentResource,\n", goName(name))
	}
	b.WriteString("\t\t// Hand-written resources — listed in handWritten in cmd/generator/main.go.\n")
	for _, n := range handWritten {
		fmt.Fprintf(&b, "\t\t%s,\n", n)
	}
	b.WriteString("\t}\n}\n")
	return []byte(b.String())
}

// writeGo formats and writes a generated file. A formatting error means the
// generated code does not parse; the raw source is written beside it.
func writeGo(path string, src []byte) error {
	formatted, err := format.Source(src)
	if err != nil {
		_ = os.WriteFile(path+".raw", src, 0o644)
		return fmt.Errorf("gofmt failed for %s (raw written to %s.raw): %w", path, path, err)
	}
	return os.WriteFile(path, formatted, 0o644)
}

func lowerFirst(s string) string {
	// A leading initialism lowers as a whole: TLSBundle → tlsBundle.
	i := 0
	for i < len(s) && s[i] >= 'A' && s[i] <= 'Z' {
		i++
	}
	switch {
	case i == 0:
		return s
	case i == 1 || i == len(s):
		return strings.ToLower(s[:i]) + s[i:]
	default:
		return strings.ToLower(s[:i-1]) + s[i-1:]
	}
}
